B.a6w=new A.B(B.q,['\u0642\u0627\u0644 \u0627\u0644\u0635\u0627\u0648\u064a: "\u0627\u0644\u0642\u0631\u0622\u0646 \u062d\u064a\u0627\u0629 \u0627\u0644\u0642\u0644\u0648\u0628."','\u0633\u0627\u0648\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0642\u0648\u0631\u0626\u0627\u0646 \u0698\u06cc\u0627\u0646\u06cc \u062f\u06b5\u06d5\u06a9\u0627\u0646\u06d5."','Al-Sawi said: "Quran is the life of hearts."'],t.w)
