B.a8b=new A.B(B.q,['\u0642\u0627\u0644 \u0627\u0644\u062e\u0631\u0634\u064a: "\u0627\u0644\u0641\u062a\u0648\u0649 \u0645\u0633\u0624\u0648\u0644\u064a\u0629 \u0639\u0638\u064a\u0645\u0629."','\u062e\u06d5\u0631\u0634\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0641\u06d5\u062a\u0648\u0627 \u0628\u06d5\u0631\u067e\u0631\u0633\u06cc\u0627\u0631\u06ce\u062a\u06cc\u06cc\u06d5\u06a9\u06cc \u06af\u06d5\u0648\u0631\u06d5\u06cc\u06d5."','Al-Kharshi said: "Fatwa is a great responsibility."'],t.w)
B.a64=new A.B(B.q,['\u0642\u0627\u0644 \u0627\u0644\u0628\u0627\u062c\u064a: "\u0627\u0644\u0646\u0642\u0644 \u0623\u0648\u0644\u0649 \u0645\u0646 \u0627\u0644\u0639\u0642\u0644."','\u0628\u0627\u062c\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0646\u06d5\u0642\u06b5 \u067e\u06ce\u0634\u062a\u0631 \u0644\u06d5 \u0639\u06d5\u0642\u06b5\u06d5."','Al-Baji said: "Transmission precedes reason."'],t.w)
B.a5Q=new A.B(B.q,['\u0642\u0627\u0644 \u0627\u0628\u0646 \u0639\u0628\u062f\u0627\u0644\u0628\u0631: "\u0627\u0644\u0639\u0644\u0645 \u0645\u0627 \u062d\u0641\u0638 \u0648\u0648\u0639\u064a."','\u0627\u0628\u0646 \u0639\u06d5\u0628\u062f\u0648\u0644\u0628\u06d5\u0695 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0632\u0627\u0646\u0633\u062a \u0626\u06d5\u0648\u06d5\u06cc\u06d5 \u0628\u067e\u0627\u0631\u06ce\u0632\u0631\u06ce\u062a \u0648 \u062a\u06ce\u0628\u06af\u06ce\u0646\u0631\u06ce\u062a."','Ibn Abd al-Barr said: "Knowledge is what is memorized and understood."'],t.w)
B.a98=new A.B(B.q,['\u0642\u0627\u0644 \u0627\u0628\u0646 \u0639\u0627\u0634\u0648\u0631: "\u0645\u0642\u0627\u0635\u062f \u0627\u0644\u0634\u0631\u064a\u0639\u0629 \u062d\u0643\u0645\u0629 \u0627\u0644\u062e\u0627\u0644\u0642."','\u0627\u0628\u0646 \u0639\u0627\u0634\u0648\u0648\u0631 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0645\u06d5\u0642\u0627\u0633\u06cc\u062f\u06cc \u0634\u06d5\u0631\u06cc\u0639\u06d5\u062a \u062d\u06cc\u06a9\u0645\u06d5\u062a\u06cc \u062f\u0631\u0648\u0633\u062a\u06a9\u06d5\u0631\u06d5."','Ibn Ashur said: "The objectives of Sharia are the Creator wisdom."'],t.w)
B.a71=new A.B(B.q,['\u0642\u0627\u0644 \u0627\u0628\u0646 \u0627\u0644\u0642\u064a\u0645: "\u0627\u0644\u0635\u0628\u0631 \u0646\u0635\u0641 \u0627\u0644\u0625\u064a\u0645\u0627\u0646."','\u0627\u0628\u0646 \u0642\u06d5\u06cc\u0645 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u0627\u0633\u0648\u0648\u062f\u06d5\u06cc\u06cc \u0646\u06cc\u0648\u06d5\u06cc \u0626\u06cc\u0645\u0627\u0646\u06d5."','Ibn al-Qayyim said: "Patience is half of faith."'],t.w)
B.a8Y=new A.B(B.q,['\u0642\u0627\u0644 \u0627\u0628\u0646 \u062a\u064a\u0645\u064a\u0629: "\u0627\u0644\u0625\u062e\u0644\u0627\u0635 \u0631\u0648\u062d \u0627\u0644\u0623\u0639\u0645\u0627\u0644."','\u0627\u0628\u0646 \u062a\u06d5\u06cc\u0645\u06cc\u06d5 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u062f\u06b5\u0633\u06c6\u0632\u06cc \u0695\u06c6\u062d\u06cc \u06a9\u0631\u062f\u0627\u0631\u06d5\u06a9\u0627\u0646\u06d5."','Ibn Taymiyyah said: "Sincerity is the spirit of deeds."'],t.w)
B.a5I=new A.B(B.q,['\u0642\u0627\u0644 \u0627\u0644\u0634\u0627\u0641\u0639\u064a: "\u0645\u0646 \u062d\u0641\u0638 \u0644\u0633\u0627\u0646\u0647 \u0633\u0644\u0645."','\u0634\u0627\u0641\u0639\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06d5\u0648\u06d5\u06cc \u0632\u0645\u0627\u0646\u06cc \u0628\u067e\u0627\u0631\u06ce\u0632\u06ce\u062a \u0633\u06d5\u0644\u0627\u0645\u06d5\u062a \u062f\u06d5\u0628\u06ce\u062a."','Al-Shafi said: "Who guards his tongue is safe."'],t.w)
B.a5M=new A.B(B.q,['\u0642\u0627\u0644 \u0645\u0627\u0644\u0643: "\u0645\u0627 \u0634\u064a\u0621 \u0623\u0646\u0641\u0639 \u0645\u0646 \u0627\u0644\u0628\u0643\u0648\u0631."','\u0645\u0627\u0644\u06a9 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0647\u06cc\u0686 \u0634\u062a\u06ce\u06a9 \u0633\u0648\u0648\u062f\u0645\u06d5\u0646\u062f\u062a\u0631 \u0646\u06cc\u06cc\u06d5 \u0644\u06d5 \u0633\u06d5\u0631\u06d5\u062a\u0627\u06cc \u0695\u06c6\u0698."','Malik said: "Nothing is more beneficial than the early morning."'],t.w)
B.a9W=new A.B(B.q,['\u0642\u0627\u0644 \u0623\u062d\u0645\u062f: "\u0644\u0648\u0644\u0627 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0644\u0645\u0627 \u0639\u0631\u0641\u062a \u0642\u062f\u0631 \u0646\u0641\u0633\u064a."','\u0626\u06d5\u062d\u0645\u06d5\u062f \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06d5\u06af\u06d5\u0631 \u0626\u06cc\u0633\u0644\u0627\u0645 \u0646\u06d5\u0628\u0648\u0627\u06cc\u06d5 \u0646\u0631\u062e\u06cc \u062e\u06c6\u0645 \u0646\u06d5\u062f\u06d5\u0632\u0627\u0646\u06cc."','Ahmad said: "Without Islam, I would not know my worth."'],t.w)
B.a7i=new A.B(B.q,['\u0642\u0627\u0644 \u0623\u0628\u0648 \u062d\u0646\u064a\u0641\u0629: "\u0627\u0644\u062a\u0641\u0642\u0647 \u0623\u0648\u0644\u0649 \u0645\u0646 \u0643\u062b\u0631\u0629 \u0627\u0644\u0639\u0628\u0627\u062f\u0629."','\u0626\u06d5\u0628\u0648 \u062d\u06d5\u0646\u06cc\u0641\u06d5 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u062a\u06d5\u0641\u06d5\u0642\u0642\u0648\u0647 \u0628\u0627\u0634\u062a\u0631\u06d5 \u0644\u06d5 \u0632\u06c6\u0631\u06cc\u0646\u06d5\u06cc \u0639\u06cc\u0628\u0627\u062f\u06d5."','Abu Hanifa said: "Understanding is better than abundant worship."'],t.w)
B.a9T=new A.B(B.q,['\u0642\u0627\u0644 \u0627\u0644\u062d\u0633\u0646: "\u0627\u0644\u0645\u0624\u0645\u0646 \u064a\u0634\u062a\u063a\u0644 \u0628\u0639\u064a\u0648\u0628\u0647 \u0639\u0646 \u0639\u064a\u0648\u0628 \u0627\u0644\u0646\u0627\u0633."','\u062d\u06d5\u0633\u06d5\u0646 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0628\u0627\u0648\u06d5\u0695\u062f\u0627\u0631 \u0628\u06d5 \u06a9\u06d5\u0645\u0648\u06a9\u0648\u0695\u06cc\u06cc\u06d5\u06a9\u0627\u0646\u06cc \u062e\u06c6\u06cc \u0633\u06d5\u0631\u0642\u0627\u06b5\u06d5 \u0644\u06d5 \u06a9\u06d5\u0645\u0648\u06a9\u0648\u0695\u06cc \u062e\u06d5\u06b5\u06a9."','Al-Hasan said: "The believer is busy with his faults from faults of others."'],t.w)
B.a7l=new A.B(B.q,['\u0642\u0627\u0644 \u0627\u0644\u0641\u0636\u064a\u0644: "\u0645\u0646 \u0639\u0631\u0641 \u0627\u0644\u0644\u0647 \u0637\u0627\u0628 \u0639\u064a\u0634\u0647."','\u0641\u0648\u0632\u06d5\u06cc\u0644 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06d5\u0648\u06d5\u06cc \u062e\u0648\u0627 \u0628\u0646\u0627\u0633\u06ce\u062a \u0698\u06cc\u0627\u0646\u06cc \u062e\u06c6\u0634 \u062f\u06d5\u0628\u06ce\u062a."','Fudayl said: "Who knows Allah, his life becomes good."'],t.w)
B.a5J=new A.B(B.q,['\u0642\u0627\u0644 \u0627\u0628\u0646 \u0627\u0644\u0645\u0628\u0627\u0631\u0643: "\u0643\u0641\u0649 \u0628\u0627\u0644\u0645\u0648\u062a \u0648\u0627\u0639\u0638\u0627\u064b."','\u0627\u0628\u0646 \u0645\u0648\u0628\u0627\u0631\u06d5\u06a9 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0645\u06d5\u0631\u06af \u0628\u06d5\u0633 \u0628\u06c6 \u0626\u0627\u0645\u06c6\u0698\u06af\u0627\u0631\u06cc."','Ibn Mubarak said: "Death is sufficient as an advisor."'],t.w)
B.a9U=new A.B(B.q,['\u0642\u0627\u0644 \u0633\u0641\u064a\u0627\u0646: "\u0644\u064a\u0633 \u0627\u0644\u0639\u0644\u0645 \u0628\u0643\u062b\u0631\u0629 \u0627\u0644\u0631\u0648\u0627\u064a\u0629 \u0648\u0644\u0643\u0646 \u0628\u0627\u0644\u062e\u0634\u064a\u0629."','\u0633\u0648\u0641\u06cc\u0627\u0646 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0632\u0627\u0646\u0633\u062a \u0628\u06d5 \u0632\u06c6\u0631\u06cc \u06af\u06ce\u0695\u0627\u0646\u06d5\u0648\u06d5 \u0646\u06cc\u06cc\u06d5 \u0628\u06d5\u06b5\u06a9\u0648 \u0628\u06d5 \u062a\u0631\u0633\u0646\u06d5."','Sufyan said: "Knowledge is not by much narration but by fear."'],t.w)
B.a7Z=new A.B(B.q,['\u0642\u0627\u0644 \u0627\u0644\u062c\u0646\u064a\u062f: "\u0645\u0646 \u0644\u0645 \u062a\u0624\u062f\u0628\u0647 \u0627\u0644\u0634\u0631\u064a\u0639\u0629 \u0644\u0645 \u064a\u0624\u062f\u0628\u0647 \u0627\u0644\u0644\u0647."','\u062c\u0648\u0646\u06d5\u06cc\u062f \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06d5\u0648\u06d5\u06cc \u0634\u06d5\u0631\u06cc\u0639\u06d5\u062a \u0626\u06d5\u062f\u06d5\u0628\u06cc \u0646\u06d5\u06a9\u0627\u062a\u060c \u062e\u0648\u0627 \u0626\u06d5\u062f\u06d5\u0628\u06cc \u0646\u0627\u06a9\u0627\u062a."','Junayd said: "Who is not disciplined by Sharia, Allah will not discipline."'],t.w)
B.a8c=new A.B(B.q,['\u0642\u0627\u0644 \u0627\u0628\u0646 \u0639\u0637\u0627\u0621: "\u0645\u0646 \u0644\u0632\u0645 \u0627\u0644\u0623\u062f\u0628 \u0644\u0632\u0645\u062a\u0647 \u0627\u0644\u0639\u0646\u0627\u064a\u0629."','\u0627\u0628\u0646 \u0639\u06d5\u062a\u0627\u0621 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06d5\u0648\u06d5\u06cc \u0626\u06d5\u062f\u06d5\u0628 \u0628\u06af\u0631\u06ce\u062a\u060c \u0686\u0627\u0648\u062f\u06ce\u0631\u06cc \u062f\u06d5\u06cc\u06af\u0631\u06ce\u062a."','Ibn Ata said: "Who adheres to manners is adhered to by care."'],t.w)
B.a8N=new A.B(B.q,['\u0642\u0627\u0644 \u0627\u0644\u0634\u0627\u0630\u0644\u064a: "\u0645\u0646 \u062f\u0644\u0643 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647 \u0641\u0647\u0648 \u0623\u062e\u0648\u0643."','\u0634\u0627\u0632\u0644\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06d5\u0648\u06d5\u06cc \u0628\u06c6 \u062e\u0648\u0627\u062a \u062f\u06d5\u06b5\u06ce\u0646\u06ce\u062a \u0626\u06d5\u0648 \u0628\u0631\u0627\u062a\u06d5."','Al-Shadhili said: "Who guides you to Allah is your brother."'],t.w)
B.a85=new A.B(B.q,['\u0642\u0627\u0644 \u0627\u0628\u0646 \u0631\u062c\u0628: "\u0627\u0644\u0642\u0644\u0628 \u0627\u0644\u0633\u0644\u064a\u0645 \u0623\u0646\u0641\u0639 \u0645\u0646 \u0627\u0644\u062c\u0633\u0645 \u0627\u0644\u0633\u0644\u064a\u0645."','\u0627\u0628\u0646 \u0695\u06d5\u062c\u06d5\u0628 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u062f\u06b5\u06cc \u0633\u0627\u063a \u0633\u0648\u0648\u062f\u0645\u06d5\u0646\u062f\u062a\u0631\u06d5 \u0644\u06d5 \u062c\u06d5\u0633\u062a\u06d5\u06cc \u0633\u0627\u063a."','Ibn Rajab said: "A sound heart is more beneficial than a sound body."'],t.w)
B.a6g=new A.B(B.q,['\u0642\u0627\u0644 \u0627\u0644\u0646\u0648\u0648\u064a: "\u0627\u0644\u062f\u0639\u0627\u0621 \u0633\u0644\u0627\u062d \u0627\u0644\u0645\u0624\u0645\u0646."','\u0646\u06d5\u0648\u06d5\u0648\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u062f\u0648\u0639\u0627 \u0686\u06d5\u06a9\u06cc \u0628\u0627\u0648\u06d5\u0695\u062f\u0627\u0631\u06d5."','Al-Nawawi said: "Dua is the weapon of the believer."'],t.w)
B.a8j=new A.B(B.q,['\u0642\u0627\u0644 \u0627\u0628\u0646 \u0627\u0644\u062c\u0648\u0632\u064a: "\u0645\u0646 \u0636\u064a\u0639 \u0648\u0642\u062a\u0647 \u0636\u064a\u0639 \u0639\u0645\u0631\u0647."','\u0627\u0628\u0646 \u062c\u06d5\u0648\u0632\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06d5\u0648\u06d5\u06cc \u06a9\u0627\u062a\u06cc \u0644\u06d5\u062f\u06d5\u0633\u062a \u0628\u062f\u0627\u062a \u062a\u06d5\u0645\u06d5\u0646\u06cc \u0644\u06d5\u062f\u06d5\u0633\u062a\u062f\u0627\u0648\u06d5."','Ibn al-Jawzi said: "Who wastes time wastes his life."'],t.w)
B.a6L=new A.B(B.q,['\u0642\u0627\u0644 \u0627\u0644\u063a\u0632\u0627\u0644\u064a: "\u0627\u0644\u0632\u0647\u062f \u0641\u064a \u0627\u0644\u0642\u0644\u0628 \u0644\u0627 \u0641\u064a \u0627\u0644\u064a\u062f."','\u063a\u06d5\u0632\u0627\u0644\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0632\u0648\u0647\u062f \u0644\u06d5 \u062f\u06b5\u06d5 \u0646\u06d5\u06a9 \u0644\u06d5 \u062f\u06d5\u0633\u062a\u062f\u0627."','Al-Ghazali said: "Asceticism is in the heart not in the hand."'],t.w)
B.a9z=new A.B(B.q,['\u0642\u0627\u0644 \u0627\u0628\u0646 \u0643\u062b\u064a\u0631: "\u0627\u0644\u0642\u0631\u0622\u0646 \u0645\u0639\u062c\u0632\u0629 \u0645\u062d\u0645\u062f \u0627\u0644\u062e\u0627\u0644\u062f\u0629."','\u0627\u0628\u0646 \u06a9\u06d5\u0633\u06cc\u0631 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0642\u0648\u0631\u0626\u0627\u0646 \u0645\u0648\u0639\u062c\u06cc\u0632\u06d5\u06cc \u0646\u06d5\u0645\u0631\u06cc \u0645\u062d\u06d5\u0645\u0645\u06d5\u062f\u06d5."','Ibn Kathir said: "Quran is Muhammad eternal miracle."'],t.w)
B.a8w=new A.B(B.q,['\u0642\u0627\u0644 \u0627\u0644\u0630\u0647\u0628\u064a: "\u0627\u0644\u0639\u062f\u0644 \u0623\u0633\u0627\u0633 \u0627\u0644\u062d\u0643\u0645."','\u0632\u06d5\u0647\u06d5\u0628\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0639\u06d5\u062f\u0627\u0644\u06d5 \u0628\u0646\u06d5\u0645\u0627\u06cc \u062d\u0648\u06a9\u0645\u06d5."','Al-Dhahabi said: "Justice is the basis of rule."'],t.w)
B.a8Z=new A.B(B.q,['\u0642\u0627\u0644 \u0627\u0628\u0646 \u062d\u062c\u0631: "\u0627\u0644\u062d\u062f\u064a\u062b \u062f\u064a\u0646 \u0641\u062a\u062d\u0641\u0638\u0648\u0647."','\u0627\u0628\u0646 \u062d\u06d5\u062c\u06d5\u0631 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u062d\u06d5\u062f\u06cc\u0633 \u0626\u0627\u06cc\u06cc\u0646\u06d5 \u0628\u06cc\u067e\u0627\u0631\u06ce\u0632\u0646."','Ibn Hajar said: "Hadith is religion so preserve it."'],t.w)
B.a7V=new A.B(B.q,['\u0642\u0627\u0644 \u0627\u0644\u0633\u064a\u0648\u0637\u064a: "\u0645\u0646 \u0623\u062d\u0628 \u0627\u0644\u0639\u0644\u0645 \u0623\u062d\u0628 \u0627\u0644\u062d\u0642."','\u0633\u06cc\u0648\u0648\u062a\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06d5\u0648\u06d5\u06cc \u062d\u06d5\u0632\u06cc \u0644\u06d5 \u0632\u0627\u0646\u0633\u062a \u0628\u06a9\u0627\u062a \u062d\u06d5\u0632\u06cc \u0644\u06d5 \u0695\u0627\u0633\u062a\u06cc\u06cc\u06d5."','Al-Suyuti said: "Who loves knowledge loves truth."'],t.w)
B.a9g=new A.B(B.q,['\u0642\u0627\u0644 \u0627\u0628\u0646 \u0628\u0627\u0632: "\u0627\u0644\u062f\u0639\u0648\u0629 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u0623\u0634\u0631\u0641 \u0627\u0644\u0623\u0639\u0645\u0627\u0644."','\u0627\u0628\u0646 \u0628\u0627\u0632 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u062f\u0627\u0648\u0627\u06a9\u0627\u0631\u06cc \u0628\u06c6 \u062e\u0648\u0627 \u0634\u06d5\u0631\u06d5\u0641\u062a\u0631\u06cc\u0646 \u06a9\u0631\u062f\u0627\u0631\u06d5."','Ibn Baz said: "Calling to Allah is the noblest deed."'],t.w)
B.a6C=new A.B(B.q,['\u0642\u0627\u0644 \u0627\u0628\u0646 \u0639\u062b\u064a\u0645\u064a\u0646: "\u0645\u0646 \u0627\u0633\u062a\u0642\u0627\u0645 \u0639\u0644\u0649 \u0637\u0631\u064a\u0642 \u0627\u0644\u062d\u0642 \u0648\u0635\u0644."','\u0627\u0628\u0646 \u0639\u0648\u0633\u06d5\u06cc\u0645\u06cc\u0646 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06d5\u0648\u06d5\u06cc \u0695\u0627\u0633\u062a \u0628\u0648\u0648 \u0644\u06d5\u0633\u06d5\u0631 \u0695\u06ce\u06af\u0627\u06cc \u0695\u0627\u0633\u062a\u060c \u06af\u06d5\u06cc\u0634\u062a."','Ibn Uthaymeen said: "Who is upright on the path of truth arrives."'],t.w)
B.a9O=new A.B(B.q,['\u0642\u0627\u0644 \u0627\u0644\u0623\u0644\u0628\u0627\u0646\u064a: "\u0627\u0644\u0633\u0646\u0629 \u062d\u0635\u0646 \u0627\u0644\u0625\u0633\u0644\u0627\u0645."','\u0626\u06d5\u0644\u0628\u0627\u0646\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0633\u0648\u0646\u0646\u06d5\u062a \u0642\u06d5\u06b5\u0627\u06cc \u0626\u06cc\u0633\u0644\u0627\u0645\u06d5."','Al-Albani said: "Sunnah is the fortress of Islam."'],t.w)
B.a94=new A.B(B.q,['\u0642\u0627\u0644 \u0639\u0645\u0631: "\u0645\u062a\u0649 \u0627\u0633\u062a\u0639\u0628\u062f\u062a\u0645 \u0627\u0644\u0646\u0627\u0633 \u0648\u0642\u062f \u0648\u0644\u062f\u062a\u0647\u0645 \u0623\u0645\u0647\u0627\u062a\u0647\u0645 \u0623\u062d\u0631\u0627\u0631\u0627\u064b."','\u0639\u0648\u0645\u06d5\u0631 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u06a9\u06d5\u06cc \u062e\u06d5\u06b5\u06a9\u062a\u0627\u0646 \u06a9\u06c6\u06cc\u0644\u06d5 \u06a9\u0631\u062f\u0648\u0648\u06d5 \u0644\u06d5\u06a9\u0627\u062a\u06ce\u06a9\u062f\u0627 \u062f\u0627\u06cc\u06a9\u0627\u0646\u06cc\u0627\u0646 \u0626\u0627\u0632\u0627\u062f \u0628\u0648\u0648\u06cc\u0646."','Umar said: "When did you enslave people when their mothers bore them free?"'],t.w)
B.a7C=new A.B(B.q,['\u0642\u0627\u0644 \u0623\u0628\u0648 \u0628\u0643\u0631: "\u0644\u0627 \u062e\u064a\u0631 \u0641\u064a \u062e\u064a\u0631 \u0628\u0639\u062f\u0647 \u0627\u0644\u0646\u0627\u0631."','\u0626\u06d5\u0628\u0648 \u0628\u06d5\u06a9\u0631 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0647\u06cc\u0686 \u0686\u0627\u06a9\u06d5 \u0646\u06cc\u06cc\u06d5 \u0644\u06d5 \u0686\u0627\u06a9\u06d5\u06cc\u06d5\u06a9 \u062f\u0648\u0627\u06cc \u0626\u0627\u06af\u0631."','Abu Bakr said: "There is no good in a good followed by Hell."'],t.w)
B.a7t=new A.B(B.q,['\u0642\u0627\u0644 \u0639\u0644\u064a: "\u0642\u064a\u0645\u0629 \u0643\u0644 \u0627\u0645\u0631\u0626 \u0645\u0627 \u064a\u062d\u0633\u0646\u0647."','\u0639\u06d5\u0644\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0646\u0631\u062e\u06cc \u0647\u06d5\u0631 \u06a9\u06d5\u0633\u06ce\u06a9 \u0626\u06d5\u0648\u06d5\u06cc\u06d5 \u0634\u0627\u0631\u06d5\u0632\u0627\u06cc \u062a\u06ce\u062f\u0627\u06cc\u06d5."','Ali said: "A person value is what he masters."'],t.w)
B.a7W=new A.B(B.q,['\u0642\u0627\u0644 \u0639\u062b\u0645\u0627\u0646: "\u0644\u0648 \u0637\u0647\u0631\u062a \u0642\u0644\u0648\u0628\u0646\u0627 \u0645\u0627 \u0634\u0628\u0639\u0646\u0627 \u0645\u0646 \u0627\u0644\u0642\u0631\u0622\u0646."','\u0639\u0648\u0633\u0645\u0627\u0646 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06d5\u06af\u06d5\u0631 \u062f\u06b5\u0645\u0627\u0646 \u067e\u0627\u06a9 \u0628\u0648\u0627\u06cc\u06d5 \u062a\u06ce\u0631 \u0646\u06d5\u062f\u06d5\u0628\u0648\u0648\u06cc\u0646 \u0644\u06d5 \u0642\u0648\u0631\u0626\u0627\u0646."','Uthman said: "If our hearts were pure, we would not tire of Quran."'],t.w)
B.a9b=new A.B(B.q,['\u0642\u0627\u0644 \u0627\u0628\u0646 \u0639\u0628\u0627\u0633: "\u0643\u0648\u0646\u0648\u0627 \u0631\u0628\u0627\u0646\u064a\u064a\u0646 \u062d\u0644\u0645\u0627\u0621 \u0641\u0642\u0647\u0627\u0621."','\u0627\u0628\u0646 \u0639\u06d5\u0628\u0627\u0633 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0695\u06d5\u0628\u0627\u0646\u06cc\u06cc\u06d5\u06a9\u0627\u0646 \u0628\u0628\u0646 \u0628\u0627 \u0628\u0631\u062f\u0628\u0627\u0631\u0627\u0646 \u0648 \u0641\u06cc\u0642\u0647\u0632\u0627\u0646\u0627\u0646."','Ibn Abbas said: "Be divine, forbearing, and understanding."'],t.w)
B.a6W=new A.B(B.q,['\u0642\u0627\u0644 \u0645\u0639\u0627\u0630: "\u0627\u0633\u062a\u0639\u064a\u0646\u0648\u0627 \u0639\u0644\u0649 \u0643\u0644 \u0635\u0646\u0639\u0629 \u0628\u0623\u0647\u0644\u0647\u0627."','\u0645\u0648\u0639\u0627\u0632 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u06cc\u0627\u0631\u0645\u06d5\u062a\u06cc \u0628\u062e\u0648\u0627\u0632\u0646 \u0644\u06d5\u0633\u06d5\u0631 \u0647\u06d5\u0645\u0648\u0648 \u06a9\u0627\u0631\u06ce\u06a9 \u0644\u06d5 \u0634\u0627\u0631\u06d5\u0632\u0627\u06a9\u0627\u0646\u06cc."','Muadh said: "Seek help for every task from its people."'],t.w)
B.a5Z=new A.B(B.q,['\u0642\u0627\u0644 \u0623\u0628\u0648 \u0630\u0631: "\u0627\u0644\u0648\u062d\u062f\u0629 \u062e\u064a\u0631 \u0645\u0646 \u062c\u0644\u064a\u0633 \u0627\u0644\u0633\u0648\u0621."','\u0626\u06d5\u0628\u0648 \u0632\u06d5\u0695 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u062a\u06d5\u0646\u06cc\u0627\u06cc\u06cc \u0628\u0627\u0634\u062a\u0631\u06d5 \u0644\u06d5 \u0647\u0627\u0648\u0695\u06ce\u06cc \u062e\u0631\u0627\u067e."','Abu Dharr said: "Solitude is better than a bad companion."'],t.w)
B.a9i=new A.B(B.q,['\u0642\u0627\u0644 \u0633\u0644\u0645\u0627\u0646: "\u0627\u0644\u0639\u0644\u0645 \u0643\u062b\u064a\u0631 \u0648\u0627\u0644\u0639\u0645\u0631 \u0642\u0635\u064a\u0631."','\u0633\u06d5\u0644\u0645\u0627\u0646 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0632\u0627\u0646\u0633\u062a \u0632\u06c6\u0631\u06d5 \u0648 \u062a\u06d5\u0645\u06d5\u0646 \u06a9\u0648\u0631\u062a\u06d5."','Salman said: "Knowledge is vast and life is short."'],t.w)
B.a75=new A.B(B.q,['\u0642\u0627\u0644 \u0623\u0628\u0648 \u0647\u0631\u064a\u0631\u0629: "\u0645\u0646 \u062d\u0633\u0646 \u0625\u0633\u0644\u0627\u0645 \u0627\u0644\u0645\u0631\u0621 \u062a\u0631\u0643\u0647 \u0645\u0627 \u0644\u0627 \u064a\u0639\u0646\u064a\u0647."','\u0626\u06d5\u0628\u0648 \u0647\u0648\u0631\u06d5\u06cc\u0631\u06d5 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0644\u06d5 \u062c\u0648\u0627\u0646\u06cc \u0626\u06cc\u0633\u0644\u0627\u0645\u06cc \u06a9\u06d5\u0633 \u0648\u0627\u0632\u0647\u06ce\u0646\u0627\u0646\u06d5 \u0644\u06d5\u0648\u06d5\u06cc \u067e\u06ce\u0648\u06d5\u0646\u062f\u06cc \u067e\u06ce\u0648\u06d5 \u0646\u06cc\u06cc\u06d5."','Abu Hurayra said: "From good Islam is leaving what does not concern you."'],t.w)
B.a7I=new A.B(B.q,['\u0642\u0627\u0644 \u0627\u0628\u0646 \u0645\u0633\u0639\u0648\u062f: "\u0645\u0646 \u0643\u0627\u0646 \u064a\u062d\u0628 \u0623\u0646 \u064a\u0639\u0644\u0645 \u0623\u0646\u0647 \u064a\u062d\u0628 \u0627\u0644\u0644\u0647 \u0641\u0644\u064a\u0639\u0631\u0636 \u0646\u0641\u0633\u0647 \u0639\u0644\u0649 \u0627\u0644\u0642\u0631\u0622\u0646."','\u0627\u0628\u0646 \u0645\u06d5\u0633\u0639\u0648\u062f \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06d5\u0648\u06d5\u06cc \u062d\u06d5\u0632\u06cc \u062f\u06d5\u06a9\u0627\u062a \u0628\u0632\u0627\u0646\u06ce\u062a \u062d\u06d5\u0632\u06cc \u0644\u06d5 \u062e\u0648\u0627\u06cc\u06d5 \u0628\u0627 \u062e\u06c6\u06cc \u0644\u06d5\u0628\u06d5\u0631 \u0642\u0648\u0631\u0626\u0627\u0646 \u0628\u06af\u0631\u06ce\u062a."','Ibn Masud said: "Who wants to know if he loves Allah should test himself with Quran."'],t.w)
B.a8q=new A.B(B.q,['\u0642\u0627\u0644 \u0639\u0627\u0626\u0634\u0629: "\u062e\u064a\u0631 \u0646\u0633\u0627\u0626\u0643\u0645 \u0645\u0646 \u062e\u0641\u062a \u0645\u0624\u0646\u062a\u0647\u0627 \u0648\u0639\u0638\u0645 \u0635\u062f\u0627\u0642\u0647\u0627."','\u0639\u0627\u0626\u06cc\u0634\u06d5 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0628\u0627\u0634\u062a\u0631\u06cc\u0646 \u0698\u0646\u0627\u0646\u062a\u0627\u0646 \u0626\u06d5\u0648\u06d5\u06cc\u06d5 \u062e\u06d5\u0631\u062c\u06cc \u06a9\u06d5\u0645\u06d5 \u0648 \u062f\u06c6\u0633\u062a\u0627\u06cc\u06d5\u062a\u06cc\u06cc\u06d5\u06a9\u06d5\u06cc \u06af\u06d5\u0648\u0631\u06d5\u06cc\u06d5."','Aisha said: "The best women are those of little expense and great friendship."'],t.w)
B.a86=new A.B(B.q,['\u0642\u0627\u0644 \u062e\u062f\u064a\u062c\u0629: "\u0648\u0627\u0644\u0644\u0647 \u0644\u0627 \u064a\u062e\u0632\u064a\u0643 \u0627\u0644\u0644\u0647 \u0623\u0628\u062f\u0627\u064b."','\u062e\u06d5\u062f\u06cc\u062c\u06d5 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0633\u0648\u06ce\u0646\u062f \u0628\u06d5\u062e\u0648\u0627 \u062e\u0648\u0627 \u0647\u06d5\u0631\u06af\u06cc\u0632 \u0695\u06cc\u0633\u0648\u0627\u062a \u0646\u0627\u06a9\u0627\u062a."','Khadija said: "By Allah, Allah will never disgrace you."'],t.w)
B.a6K=new A.B(B.q,['\u0642\u0627\u0644 \u0641\u0627\u0637\u0645\u0629: "\u0625\u0646\u0645\u0627 \u0627\u0644\u0639\u0632 \u0628\u0627\u0644\u0644\u0647 \u0644\u0627 \u0628\u063a\u064a\u0631\u0647."','\u0641\u0627\u062a\u06cc\u0645\u06d5 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0633\u06d5\u0631\u0628\u06d5\u0631\u0632\u06cc \u062a\u06d5\u0646\u0647\u0627 \u0628\u06d5 \u062e\u0648\u0627\u06cc\u06d5 \u0646\u06d5\u06a9 \u0628\u06d5 \u063a\u06d5\u06cc\u0631\u06cc."','Fatima said: "Honor is only with Allah, not with others."'],t.w)
B.a7A=new A.B(B.q,['\u0642\u0627\u0644 \u0627\u0644\u062d\u0633\u0646 \u0628\u0646 \u0639\u0644\u064a: "\u0644\u0648\u0644\u0627 \u062b\u0644\u0627\u062b \u0644\u0645\u0627 \u0623\u0628\u0627\u0644\u064a \u0648\u0644\u0648 \u0623\u0635\u0628\u062d\u062a \u0641\u064a \u0627\u0644\u0646\u0627\u0631: \u0627\u0644\u062a\u0648\u0628\u0629 \u0648\u0627\u0644\u0639\u0641\u0648 \u0648\u0627\u0644\u0631\u062d\u0645\u0629."','\u062d\u06d5\u0633\u06d5\u0646\u06cc \u06a9\u0648\u0695\u06cc \u0639\u06d5\u0644\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06d5\u06af\u06d5\u0631 \u0633\u06ce \u0634\u062a \u0646\u06d5\u0628\u0648\u0627\u06cc\u06d5 \u06af\u0648\u06ce\u0645 \u0646\u06d5\u062f\u06d5\u0628\u0648\u0648 \u0626\u06d5\u06af\u06d5\u0631 \u0628\u06a9\u06d5\u0648\u0645\u06d5 \u0626\u0627\u06af\u0631\u06d5\u0648\u06d5: \u062a\u06d5\u0648\u0628\u06d5\u060c \u0644\u06ce\u062e\u06c6\u0634\u0628\u0648\u0648\u0646\u060c \u0695\u06d5\u062d\u0645\u06d5\u062a."','Al-Hasan ibn Ali said: "Were it not for three things, I would not care if I entered Hell: repentance, pardon, and mercy."'],t.w)
B.a6Z=new A.B(B.q,['\u0642\u0627\u0644 \u0627\u0644\u062d\u0633\u064a\u0646 \u0628\u0646 \u0639\u0644\u064a: "\u0627\u0644\u0646\u0627\u0633 \u0639\u0628\u064a\u062f \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0627\u0644\u062f\u064a\u0646 \u0644\u0639\u0642 \u0639\u0644\u0649 \u0623\u0644\u0633\u0646\u062a\u0647\u0645."','\u062d\u0648\u0633\u06d5\u06cc\u0646\u06cc \u06a9\u0648\u0695\u06cc \u0639\u06d5\u0644\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u062e\u06d5\u06b5\u06a9 \u06a9\u06c6\u06cc\u0644\u06d5\u06cc \u062f\u0648\u0646\u06cc\u0627\u0646 \u0648 \u0626\u0627\u06cc\u06cc\u0646 \u0644\u06d5\u0633\u06d5\u0631 \u0632\u0645\u0627\u0646\u06cc\u0627\u0646\u06d5."','Al-Husayn said: "People are slaves of the world and religion is on their tongues."'],t.w)
B.a7b=new A.B(B.q,['\u0642\u0627\u0644 \u0632\u064a\u0646 \u0627\u0644\u0639\u0627\u0628\u062f\u064a\u0646: "\u0627\u0644\u0631\u0636\u0627 \u0628\u0627\u0644\u0642\u0636\u0627\u0621 \u0631\u0623\u0633 \u0627\u0644\u0625\u064a\u0645\u0627\u0646."','\u0632\u06d5\u06cc\u0646\u0648\u0644\u0639\u0627\u0628\u06cc\u062f\u06cc\u0646 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0695\u0627\u0632\u06cc\u0628\u0648\u0648\u0646 \u0628\u06d5 \u0642\u06d5\u062f\u06d5\u0631 \u0633\u06d5\u0631\u06cc \u0626\u06cc\u0645\u0627\u0646\u06d5."','Zayn al-Abidin said: "Contentment with decree is the head of faith."'],t.w)
B.a9o=new A.B(B.q,['\u0642\u0627\u0644 \u062c\u0639\u0641\u0631 \u0627\u0644\u0635\u0627\u062f\u0642: "\u0645\u0646 \u0639\u0631\u0641 \u0646\u0641\u0633\u0647 \u0641\u0642\u062f \u0639\u0631\u0641 \u0631\u0628\u0647."','\u062c\u06d5\u0639\u0641\u06d5\u0631\u06cc \u0633\u0627\u062f\u0642 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06d5\u0648\u06d5\u06cc \u062e\u06c6\u06cc \u0628\u0646\u0627\u0633\u06ce\u062a \u067e\u06d5\u0631\u0648\u06d5\u0631\u062f\u06af\u0627\u0631\u06cc \u0646\u0627\u0633\u06cc\u0648\u06d5."','Jafar al-Sadiq said: "Who knows himself has known his Lord."'],t.w)
